window.docContents[242].resolve({"/Gamma-Function/___5___2-Definitions/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___2-Definitions--___5___2_LPAR_i_RPAR_-Gamma-and-Psi-Functions":{"contents":"\\Gamma(z)=\\int_0^\\infty e^{-t}t^{z-1}\\,dt,\\qquad \\Re z>0.For a complex number with positive real part, the Gamma function is Euler's integral on the positive\nreal axis. The first declaration verifies convergence of that integral; the second states its value.\n\n","context":"LMLF · DLMF with Lean\u0009Gamma Function\u0009§5.2 Definitions","header":"§5.2(i) Gamma and Psi Functions","id":"/Gamma-Function/___5___2-Definitions/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___2-Definitions--___5___2_LPAR_i_RPAR_-Gamma-and-Psi-Functions"}});